import{z as n,x as s,o as e,c as m,q as r,j as B,D as E,d as A,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"方差互换的深化","description":"","frontmatter":{"title":"方差互换的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/vt-variance-swap-deep.md","filePath":"quant/vt-variance-swap-deep.md","lastUpdated":1791413859000}'),o={name:"quant/vt-variance-swap-deep.md"};function d(p,a,h,u,_,c){const t=s("Mermaid");return e(),m("div",null,[a[2]||(a[2]=r('<h1 id="方差互换的深化" tabindex="-1">方差互换的深化 <a class="header-anchor" href="#方差互换的深化" aria-label="Permalink to &quot;方差互换的深化&quot;">​</a></h1><div class="epigraph"><p>方差互换把一段路径压缩成一个执行价；签名只要一行，持有期的全部麻烦——delta、carry、凸性、跳、拥挤——都藏在那一行底下。</p><footer>—— 据 Demeterfi, Derman, Kamal and Zou, 1999；Carr and Madan, 1998 整理</footer></div><p><a href="/quant/vt-forecast-competition">上一课</a>把波动预测整理成可竞赛、可评估的栈，并说明预测只有接上正确的收益几何才有用。缺口随之而来：预测的对象是已实现方差，要下注必须把方差变成可持有、可对冲、可盯市的合同。<a href="/quant/var-swap-replication">方差互换复制</a>讲过条带怎么给出公平方差，<a href="/quant/variance-swap-vix">方差互换与 VIX</a> 讲了与 VIX 的关系，<a href="/quant/var-vs-vol-swap">方差与波动互换</a>拆过开方凸性。本课不再推导复制，写持有期本身：怎么进、怎么记账、怎么对冲、怎么死。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(K_{\\mathrm{var}}\\) 是今天条带按无套利给出的公平方差，不是你对 RV 的预测；交易的本质是「预测减执行价」。但持有期的盈亏不是「结算 RV 减 \\(K\\)」一条线：盯市先于结算，复制条带给合同带来 delta，<a href="/quant/vix-term-structure-trade">期限结构</a>在动，凸性与跳的残差不对称。更麻烦的是方向：做空方差是收<a href="/quant/variance-risk-premium">方差风险溢价</a>的主流做法，但隐波跳升时空头按盯市先赔钱——把路径盈亏与到期结算混在一个桶里，任何复盘都说不清这笔交易是错在了预测还是错在了活不到结算。<span class="marginnote">\\(K_{\\mathrm{var}}\\) 不是你对未来的猜测，而是今天市场给公平方差的报价——就像保险的保费，无关你信不信会出事。交易因此被压缩成一道减法：你的预测减市场报价，正的部分才是你进场拿溢价的理由。</span></p><h3 id="持有期四栏账" tabindex="-1">持有期四栏账 <a class="header-anchor" href="#持有期四栏账" aria-label="Permalink to &quot;持有期四栏账&quot;">​</a></h3><ul><li>carry：把（预测 RV 减 \\(K_{\\mathrm{var}}\\)）除以 \\(K_{\\mathrm{var}}\\) 年化当预期收益，同时把预测误差的分布写进同一份报告。</li><li>delta：复制条带随现货移动产生 delta，集中在平值附近，用期货按公式对冲；对冲本身在赚赔 \\(\\tfrac12\\Gamma S^2(\\mathrm{RV}-\\sigma_{\\mathrm{imp}}^2)\\)，见 <a href="/quant/gamma-scalping-pnl">Gamma scalping 恒等式</a>。</li><li>期限结构：到期前的平仓价由曲面与方差曲线定，滚动仓位按方差桶记账，桶随到期挪动。</li><li>残差：开方凸性（若做的是波动互换）、跳余项与条带截断，列入「已知不可对冲」清单。</li></ul><p><span class="marginnote">carry 栏给个数字实例：预测已实现方差 1600、执行价 \\(K_{\\mathrm{var}}\\) 2000（方差点，开根号即波动率 40% 对约 44.7%），代入 (1600−2000)/2000 = −0.2——做多方年化预期约亏两成，做空反之一年预期收两成。这道除法就是四栏账里「预期收益」的全部算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进出场分两步。进场用条带：OTC 直接按 \\(K_{\\mathrm{var}}\\) 成交，或在上市市场用近月与次月期权拼条带——后者多了执行与保证金，少了对手方信用。出场分「持有到期」与「提前平仓」两种口径：前者结已实现方差，后者结远期方差的市场重估，两者不是同一个数，报告必须分开。滚动的仓位按方差桶而非月份标签管理，与 <a href="/quant/vix-term-structure-trade">VIX 期限结构</a>的桶语言一致。</p><p>对冲按四栏账的第二栏执行：条带 delta 主要由平值跨式贡献，对冲工具用标的期货；<a href="/quant/delta-hedge-freq">对冲频率</a>的带宽由 Gamma 与成本定，不因合同是 OTC 而改变。</p>',11)),(e(),B(i,null,{default:E(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20STRIP%5B%22%E6%9D%A1%E5%B8%A6%E5%AE%9A%E4%BB%B7%20%E7%BB%99%E5%87%BA%20K_var%22%5D%20--%3E%20GAP%5B%22%E9%A2%84%E6%B5%8B%20RV%20%E4%B8%8E%20K_var%20%E4%B9%8B%E5%B7%AE%22%5D%0A%20%20GAP%20--%3E%20POS%5B%22%E5%BB%BA%E4%BB%93%EF%BC%9AOTC%20%E6%88%96%E6%8B%BC%E6%9D%A1%E5%B8%A6%22%5D%0A%20%20POS%20--%3E%20DAILY%5B%22%E6%AF%8F%E6%97%A5%EF%BC%9Adelta%20%E5%AF%B9%E5%86%B2%20%E5%8A%A0%20carry%20%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20DAILY%20--%3E%20EXIT%7B%22%E5%87%BA%E5%9C%BA%E5%8F%A3%E5%BE%84%22%7D%0A%20%20EXIT%20--%3E%7C%22%E6%8C%81%E6%9C%89%E5%88%B0%E6%9C%9F%22%7C%20SETTLE%5B%22%E7%BB%93%E7%AE%97%E5%B7%B2%E5%AE%9E%E7%8E%B0%E6%96%B9%E5%B7%AE%22%5D%0A%20%20EXIT%20--%3E%7C%22%E6%8F%90%E5%89%8D%E5%B9%B3%E4%BB%93%22%7C%20MTM%5B%22%E7%BB%93%E8%BF%9C%E6%9C%9F%E6%96%B9%E5%B7%AE%E9%87%8D%E4%BC%B0%22%5D%0A%20%20SETTLE%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%87%B8%E6%80%A7%20%E8%B7%B3%20%E6%88%AA%E6%96%AD%22%5D%0A%20%20MTM%20--%3E%20RES%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(1/K^2\\) 权重使左翼主导定价：条带价值的大头来自虚值看跌，于是现货大跌后条带 delta 按凸性上跳，次日的对冲账单自动变大——对冲预算要按「跌过之后」留，不按平均日留。这也是方差互换「纯方差暴露」的另一面：纯的是结算变量，不是持有路径。</p><p>溢价的经济来路要写清：卖方差收的是风险价格，不是错误定价，尾部由<a href="/quant/short-vol-tail">波动率卖方</a>的左尾凸性支付。与 <a href="/quant/gamma-swap">Gamma swap</a> 的价差是干净的偏度仓位，别让方差与偏度混进同一个 PnL 桶，否则<a href="/quant/skew-risk-premium">偏度风险溢价</a>与方差溢价会互相污染归因。</p>',3)),(e(),B(i,null,{default:E(()=>[l(t,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E6%9D%A1%E5%B8%A6%E6%9D%83%E9%87%8D%201%2FK%C2%B2%22%5D%20--%3E%20L%5B%22%E5%B7%A6%E7%BF%BC%E8%99%9A%E5%80%BC%E7%9C%8B%E8%B7%8C%E4%B8%BB%E5%AF%BC%E5%AE%9A%E4%BB%B7%22%5D%0A%20%20CRASH%5B%22%E7%8E%B0%E8%B4%A7%E5%A4%A7%E8%B7%8C%22%5D%20--%3E%20ITM%5B%22%E5%B7%A6%E7%BF%BC%E6%9C%9F%E6%9D%83%E6%89%B9%E9%87%8F%E5%8F%98%E5%AE%9E%E5%80%BC%22%5D%0A%20%20ITM%20--%3E%20J%5B%22%E6%9D%A1%E5%B8%A6%20delta%20%E6%8C%89%E5%87%B8%E6%80%A7%E4%B8%8A%E8%B7%B3%22%5D%0A%20%20J%20--%3E%20B%5B%22%E6%AC%A1%E6%97%A5%E5%AF%B9%E5%86%B2%E8%B4%A6%E5%8D%95%E8%87%AA%E5%8A%A8%E5%8F%98%E5%A4%A7%22%5D%0A%20%20B%20--%3E%20Q%7B%22%E5%AF%B9%E5%86%B2%E9%A2%84%E7%AE%97%E6%8C%89%E5%93%AA%E4%B8%AA%E5%8F%A3%E5%BE%84%E7%95%99%22%7D%0A%20%20Q%20--%3E%7C%22%E5%B9%B3%E5%9D%87%E6%97%A5%22%7C%20POOR%5B%22%E9%A2%84%E7%AE%97%E8%A2%AB%E5%8E%8B%E5%8A%9B%E6%97%A5%E6%89%93%E7%A9%BF%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B7%8C%E5%90%8E%E8%B4%A6%E5%8D%95%22%7C%20OK%5B%22%E5%B9%B3%E7%A8%B3%E7%A9%BF%E8%BF%87%E5%8E%8B%E5%8A%9B%E6%97%A5%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<p><span class="marginnote">盯市像每天按市价重估你的赌注：赌局还没散场，赌注已经天天过手。所以隐波跳升时空头「预测正确」救不了当天的账——钱先离开口袋，预言要到结算那天才轮到它说话。仓位设计的第一问因此不是「看得对不对」，而是「中间那段赔钱撑不撑得住」。</span></p><p><span class="marginnote">2007 年 8 月的量化危机复盘里，大量基金经由方差互换与期权结构做空波动；隐波跳升时空头按盯市先亏，保证金与限额在「收敛」到来之前就行动。合同结构决定了坏消息先到：共识正确救不了仓位，活得到结算才行。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推条带复制，也不处理 OTC 的信用与抵押——那是合同工程，归场外课程。个股方差互换的股息与借券处理一句带过：股息不确定时条带要用股息互换配套。「方差互换是纯波动暴露」这句话在本课程里不成立：它是纯方差暴露，对波动平方根的凸性差额是另一份合同的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交易的本质是预测 RV 减 \\(K_{\\mathrm{var}}\\)；持有期盈亏必须拆成 carry、delta、期限、残差四栏。</li><li>出场分「结算已实现」与「盯市平仓」两种口径，报告分开写。</li><li>条带左翼主导：大跌后 delta 凸性上升，对冲预算按跌后账单留。</li><li>卖方收的是风险溢价，与 Gamma swap 的价差是偏度仓位，归因不得混桶。</li><li>拥挤是结构性风险：盯市先于收敛，活到结算是仓位设计的一部分。</li><li>出处：Carr and Madan, 1998；Demeterfi, Derman, Kamal and Zou, 1999；凸性与条带详见复制与凸性两课。</li></ul>',6))])}const f=n(o,[["render",d]]);export{D as __pageData,f as default};
